const heads = runGit(fleet.root, [
  "for-each-ref",
  "--format=%(refname:short)",
  "refs/remotes/origin",
]);
for (const line of heads.stdout.split("\n")) {
  const name = line.trim();
  if (name.length > 0 && name !== "origin/main") {
    items.push({ kind: "task", id: name, detail: "unmerged branch" });
  }
}
return items.sort((a, b) => `${a.kind}/${a.id}`.localeCompare(`${b.kind}/${b.id}`));

